/**
 * Public repair tracking — shared, client-safe helpers.
 * The public follow-up page only ever shows the whitelisted fields built here;
 * the token is generated by the database (gen_random_bytes), never by the browser.
 */
import type { RepairStatus } from "./repairs";

/** 24 random bytes hex-encoded by the database = 48 lowercase hex chars. */
export const TRACKING_TOKEN_PATTERN = /^[0-9a-f]{48}$/;

export function isValidTrackingToken(token: string): boolean {
  return TRACKING_TOKEN_PATTERN.test(token);
}

/** Repair references look like REP-2026-0001 (per-shop yearly counter). */
export const REFERENCE_PATTERN = /^REP-\d{4}-\d{4,}$/;

/** Normalizes a scanned or typed reference: trim, uppercase, single dashes. */
export function normalizeReference(input: string): string {
  return input
    .trim()
    .toUpperCase()
    .replace(/[\s_]+/g, "-")
    .replace(/-+/g, "-");
}

export function isValidReference(input: string): boolean {
  return REFERENCE_PATTERN.test(normalizeReference(input));
}

/* ---------- Public progress steps ---------- */

export const PUBLIC_STEPS = ["recu", "diagnostic", "en_cours", "pret", "restitue"] as const;
export type PublicStep = (typeof PUBLIC_STEPS)[number];

export const PUBLIC_STEP_LABELS: Record<PublicStep, string> = {
  recu: "Reçu",
  diagnostic: "Diagnostic",
  en_cours: "En cours",
  pret: "Prêt",
  restitue: "Restitué",
};

/** Explicit mapping between internal statuses and public steps. */
export function toPublicStep(status: RepairStatus): PublicStep | "annule" {
  switch (status) {
    case "recu":
      return "recu";
    case "diagnostic":
      return "diagnostic";
    case "attente_validation":
    case "attente_piece":
    case "en_reparation":
    case "tests":
      return "en_cours";
    case "termine":
      return "pret";
    case "restitue":
      return "restitue";
    case "annule":
      return "annule";
  }
}

export interface PublicTimelineEntry {
  step: PublicStep;
  reachedAt: string | null;
}

/**
 * Builds the public timeline from the real status history.
 * A step is "reached" only when at least one history entry maps to it;
 * its timestamp is the earliest matching entry. No date is ever invented.
 * Unknown statuses are ignored rather than producing a misleading progress.
 */
export function buildPublicTimeline(
  history: { status: string; created_at: string }[],
): PublicTimelineEntry[] {
  const reached = new Map<PublicStep, string>();
  for (const entry of history) {
    const step = toPublicStep(entry.status as RepairStatus);
    if (step === "annule") continue;
    const previous = reached.get(step);
    if (!previous || entry.created_at < previous) reached.set(step, entry.created_at);
  }
  return PUBLIC_STEPS.map((step) => ({ step, reachedAt: reached.get(step) ?? null }));
}

/** Current public step = last reached step in chronological order, or null. */
export function currentPublicStep(timeline: PublicTimelineEntry[]): PublicStep | null {
  for (let i = timeline.length - 1; i >= 0; i -= 1) {
    if (timeline[i].reachedAt) return timeline[i].step;
  }
  return null;
}

/* ---------- Whitelisted public payload ---------- */

export interface PublicTrackingDto {
  reference: string;
  cancelled: boolean;
  device: {
    brand: string;
    model: string;
    storage: string | null;
    color: string | null;
  };
  timeline: PublicTimelineEntry[];
  currentStep: PublicStep | null;
  shop: {
    name: string;
    address: string | null;
    phone: string | null;
  };
}

/**
 * Builds the public payload from full rows. Only the fields listed here ever
 * leave the server: no IMEI, no customer identity, no internal notes, no ids.
 */
export function buildPublicTrackingDto(input: {
  repair: {
    reference: string;
    status: string;
    brand: string;
    model: string;
    storage: string | null;
    color: string | null;
  };
  history: { status: string; created_at: string }[];
  shop: { name: string; address: string | null; phone: string | null };
}): PublicTrackingDto {
  const timeline = buildPublicTimeline(input.history);
  return {
    reference: input.repair.reference,
    cancelled: input.repair.status === "annule",
    device: {
      brand: input.repair.brand,
      model: input.repair.model,
      storage: input.repair.storage,
      color: input.repair.color,
    },
    timeline,
    currentStep: currentPublicStep(timeline),
    shop: {
      name: input.shop.name,
      address: input.shop.address,
      phone: input.shop.phone,
    },
  };
}
